WITH cr_agg AS (SELECT cr_refunded_customer_sk AS cust_sk, SUM(cr_net_loss) AS total_return_loss, SUM(cr_return_amount) AS total_return_amount, COUNT(*) AS return_cnt FROM catalog_returns GROUP BY cr_refunded_customer_sk), ws_agg AS (SELECT ws_bill_customer_sk AS cust_sk, SUM(ws_net_profit) AS total_sales_profit, SUM(ws_ext_sales_price) AS total_sales_revenue, COUNT(*) AS sales_cnt FROM web_sales GROUP BY ws_bill_customer_sk) SELECT c.c_customer_id, COALESCE(cr.total_return_loss, 0) AS total_return_loss, COALESCE(ws.total_sales_profit, 0) AS total_sales_profit, (COALESCE(ws.total_sales_profit, 0) - COALESCE(cr.total_return_loss, 0)) AS net_balance, CASE WHEN COALESCE(ws.total_sales_profit, 0) > COALESCE(cr.total_return_loss, 0) THEN 'Profit' WHEN COALESCE(ws.total_sales_profit, 0) < COALESCE(cr.total_return_loss, 0) THEN 'Loss' ELSE 'Break-even' END AS balance_status, RANK() OVER (ORDER BY (COALESCE(ws.total_sales_profit, 0) - COALESCE(cr.total_return_loss, 0)) DESC) AS profit_rank FROM customer c LEFT JOIN cr_agg cr ON cr.cust_sk = c.c_customer_sk LEFT JOIN ws_agg ws ON ws.cust_sk = c.c_customer_sk WHERE c.c_preferred_cust_flag = 'Y' ORDER BY net_balance DESC LIMIT 50
